+		L[3] = -L[2].y * L[3] + L[3].y * L[2];
+		L[2] = -L[2].y * L[1] + L[1].y * L[2];
+	} else if (config == 12) // V3 V4 clip V1 V2
+	{
+		vertex_count = 4;
+		L[1] = -L[1].y * L[2] + L[2].y * L[1];
+		L[0] = -L[0].y * L[3] + L[3].y * L[0];
+	} else if (config == 13) // V1 V3 V4 clip V2
+	{
+		vertex_count = 5;
+		L[4] = L[3];
+		L[3] = L[2];
+		L[2] = -L[1].y * L[2] + L[2].y * L[1];
